import {centerTasks,securityTasks} from './centers.mjs';
import {goalStatus} from './model.mjs';
import {permissionView} from './permission-view.mjs?v=scope2';
import {permissionState,risk} from './permissions.mjs?v=scope2';
import {icon} from './icons.mjs?v=demo5-security-2';
import {LiveProgressCard} from './live-card.mjs?v=demo5-security-2';
import {DockFlip} from './dock-flip.mjs';
import {runningAppKeys,canDismissTaskHover,launcherWindow,windowVisible,closeWindow,toggleWindow,toggleStart,claimAgentWindow,toggleAgent,releaseAgentHover} from './surfaces.mjs?v=demo5-security-2';
import {AGENTS,AGENT_ORDER,goalAgents,notificationTasks,ideaChannel,ORDINARY_APPS,APP_NAMES,CONNECTIONS,STORAGE_KEY,seedState,reduce,loadState,saveState,statusInfo,hoverDetail} from './model.mjs?v=demo5-security-2';

const $=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state=loadState(localStorage);
const ui={windows:new Map(),z:10,section:state.ideaOpen?'ideas':'goals',connection:'mail',activeTasks:{},agentSurfaces:{},suppressedAgents:new Set(),hoveredAgent:null,focusedAgent:null,outputGoal:state.selectedGoal,outputId:null,activeDraft:'personal',botInput:'',dockInput:'',agent:'xiaoyi',manual:state.session.manualText,choice:'专业用户',launcher:false,apps:false,pinnedAgent:null,sidebar:false,storageWarn:false,liveExpanded:false,liveScroll:0,notifications:false,hangerOpen:true};
const AI_DESKTOP_COPY='AI桌面--老板模式： 任务指令一步直达， Agent状态一步直达，Bot全程帮你管 ；';
const NORMAL_DESKTOP_COPY='传统桌面--古法办公模式';
const BOT_WINDOW_TITLE='我的工作幕僚长： 统一目标.跨Agent协作. 统一任务管理.关键决策找你';
const desktop=$('#desktop');
// Persistent siblings keep the Dock animation alive while task windows refresh.
desktop.innerHTML='<div id=desktop-content></div><div id=dock-mount></div>';
const desktopContent=$('#desktop-content'),dockMount=$('#dock-mount');
const liveDrafts=new Map();
const liveCard=new LiveProgressCard({host:$('#live-card-host'),drafts:liveDrafts,getTask:id=>state.tasks.find(t=>t.id===id),onOpen:openTask,onSend:(task,text)=>dispatch({type:'SUPPLEMENT_TASK',task,text})});
const motionPreference=matchMedia('(prefers-reduced-motion: reduce)');
const dockFlip=new DockFlip({
 getMode:()=>state.mode,
 reduced:()=>motionPreference.matches,
 prepare:()=>{ui.apps=false;ui.launcher=false;ui.pinnedAgent=null;ui.hoveredAgent=null;ui.focusedAgent=null;for(const agent of AGENT_ORDER)ui.suppressedAgents.add(agent);liveCard.suspend();},
 commit:mode=>dispatch({type:'MODE',mode},{renderNow:false}),
 phaseChanged:()=>render({forceDock:true}),
 finished:()=>liveCard.resume(),
});
motionPreference.addEventListener('change',event=>{if(event.matches)dockFlip.settle();});
let toastTimer;
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3300);}
function dispatch(event,{renderNow=true}={}){const next=reduce(state,event);if(next===state)return;state=next;if(!saveState(localStorage,state)&&!ui.storageWarn){ui.storageWarn=true;toast('浏览器存储不可用，本次内容仅保留在当前页面');}if(renderNow)render();}
function badge(task){const [label,color,symbol]=statusInfo(task);return `<span class="status ${color}">${icon(symbol)}${label}</span>`;}
function appIcon(name,size=''){return `<span class="app-icon ${name} ${size}">${icon(AGENTS[name]?.icon||name)}</span>`;}
function goalAgentIcons(goal){const agents=goalAgents(state,goal);const names=agents.map(a=>AGENTS[a].name).join('、');return `<span class="goal-agent-icons ${agents.length>2?'fanned':''}" data-agent-count="${agents.length}" title="协作 Agent：${names}" aria-label="协作 Agent：${names}">${agents.map((a,i)=>`<span class="goal-agent-card" style="--fan-angle:${(i-(agents.length-1)/2)*12}deg;--fan-i:${i}" title="${AGENTS[a].name}">${appIcon(a,'small')}</span>`).join('')}</span>`;}
function collaborators(goal){return goalAgents(state,goal).map(agent=>`<span title="${AGENTS[agent].name}" aria-label="${AGENTS[agent].name}">${appIcon(agent,'small')}</span>`).join('');}
function botSource(t){return t.source==='bot'?`<span class="bot-source" title="Bot 下发的任务" aria-label="Bot 下发的任务">${icon('bot')}<span>Bot</span></span>`:'';}
function taskWindows(t){return [...ui.windows.values()].filter(w=>w.task===t.id);}
function windowTile(w){return `<button class="window-tile" data-action="restore-window" data-window="${w.id}">${icon(w.id==='computer'?'computer':'editor')}<span><strong>${esc(w.id==='computer'?'Computer Use':state.drafts[w.output]?.title||APP_NAMES[w.app]||'窗口')}</strong><small>${w.id==='computer'?esc(({agent:'Agent 操作中',human:'人工接管中',requesting_human:'等待暂停 ACK',requesting_agent:'等待交还 ACK'})[state.session.phase]):w.minimized?'已最小化 · 点击恢复':'已打开 · 点击查看'}</small><em class=window-excerpt>${esc(w.id==='computer'?state.session.context:state.drafts[w.output]?.text?.slice(0,72)||'模拟应用窗口')}</em></span></button>`;}
function currentGoal(){return state.goals.find(g=>g.id===state.selectedGoal)||state.goals[0];}
function showWindow(id,opts={}){
  if(!ui.windows.has(id)){
    const specs={bot:[1000,590,150,145],editor:[820,570,65,118],computer:[930,570,270,145],output:[900,570,220,150],guide:[700,510,340,170]};
    const [w,h,x,y]=specs[id]||[760,510,330,160];
    const width=Math.min(w,innerWidth-36),height=Math.min(h,innerHeight-235);
    ui.windows.set(id,{id,preferredW:opts.w||w,preferredH:opts.h||h,w:width,h:Math.max(310,height),x:Math.max(18,Math.min(x,innerWidth-width-18)),y:Math.max(110,Math.min(y,innerHeight-height-120)),z:++ui.z});
  }
  Object.assign(ui.windows.get(id),{minimized:false,z:++ui.z},opts);
}
function openTask(id){ui.hangerOpen=false;ui.notifications=false;liveCard.dismiss(true);liveCard.blocked.add(id);const task=state.tasks.find(t=>t.id===id);if(!task)return;ui.activeTasks[task.agent]=id;claimAgentWindow(ui,task.agent);dispatch({type:'VIEW',task:id},{renderNow:false});showWindow('agent-'+task.agent);render();}
function openOutput(goal,id){ui.outputGoal=goal;const outputs=state.outputs.filter(o=>o.goal===goal);ui.outputId=id||outputs.at(-1)?.id;if(ui.outputId)dispatch({type:'VIEW_OUTPUT',output:ui.outputId},{renderNow:false});showWindow('output');render();}
function openDraft(output){const o=state.outputs.find(o=>o.id===output);if(!o)return;const t=state.tasks.find(t=>t.id===o.task);dispatch({type:'OPEN_DRAFT',output},{renderNow:false});showWindow('doc-'+output,{output,task:t?.id,agent:t?.agent});ui.pinnedAgent=null;render();}
function revealDockApp(app){document.querySelector(`.dock .dock-app[data-app="${app}"]`)?.scrollIntoView({block:'nearest',inline:'nearest',behavior:'auto'});}
function openApp(app){const existing=[...ui.windows.values()].filter(w=>w.app===app||(app==='editor'&&w.id==='editor')).sort((a,b)=>b.z-a.z)[0];const id=existing?.id||launcherWindow('app',app);showWindow(id,{app});ui.launcher=false;ui.apps=false;render();revealDockApp(app);}

function statusBar(){
 const time=new Date().toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit',hour12:false});
 return `<header class="systembar"><div class="system-left"><button id="notification-toggle" class="notification-toggle" data-action="notifications" aria-label="查看通知" aria-expanded="${ui.notifications}" aria-controls="notification-panel" title="通知 · ${notificationTasks(state).length} 项待处理">${icon('bell')}${notificationTasks(state).length?`<span class="notification-badge" aria-hidden="true">${notificationTasks(state).length}</span>`:''}</button></div>${liveCapsule()}<div class="system-right"><span class="prototype-dot"></span><span class="prototype-label">本地交互原型 · 所有操作均为模拟</span><span class="system-divider"></span>${icon('wifi')}${icon('battery')}<span class="date">10 月 26 日</span><time>${time}</time></div></header>`;
}
function notificationPanel(){if(!ui.notifications)return '';const tasks=notificationTasks(state);return `<aside id="notification-panel" class="notification-panel" role="dialog" aria-modal="false" aria-label="通知"><header><h2 id="notification-heading" tabindex="-1">通知 <span>${tasks.length}</span></h2><button data-action="notifications" aria-label="关闭通知">${icon('close')}</button></header><div class="notification-list">${tasks.length?tasks.map(t=>`<button class="notification-entry" data-action="task" data-task="${t.id}">${appIcon(t.agent,'small')}<span><strong>${esc(t.title)}</strong>${badge(t)}<small>${esc(t.step)}</small></span>${icon('right')}</button>`).join(''):`<div class="notification-empty">${icon('bell')}<h3>暂无待处理通知</h3><p>任务需要确认、补充或有新结果时，会显示在这里。</p></div>`}</div><footer>模拟任务提醒 · 查看不会授权或发布</footer></aside>`;}
function liveCapsule(){
 const priority={auth:0,input:1,result:2,failed:3,running:4,pausing:0,paused:5,resuming:4};
 const tasks=state.tasks.filter(t=>['auth','input','failed','running','pausing','resuming'].includes(t.status)||(t.status==='result'&&t.unread)).sort((a,b)=>(priority[a.status]??6)-(priority[b.status]??6));
 const representatives=[];for(const t of tasks)if(!representatives.some(x=>x.agent===t.agent))representatives.push(t);
 return `<aside class="live-capsule ${ui.liveExpanded?'is-expanded':''}" aria-label="AI 实况"><button id="live-summary" class="live-heading" data-action="live-summary" aria-label="${innerWidth<=760?(ui.liveExpanded?'收起 AI 实况状态':'展开 AI 实况状态'):'查看 AI 实况状态'}" ${innerWidth<=760?`aria-expanded="${ui.liveExpanded}" aria-controls="menu-live-items"`:''}><span class="live-orbit"></span><span>AI 实况</span><span class="live-count">${tasks.length}</span>${icon('chevron')}</button><div id="menu-live-items" class="live-items" ${innerWidth<=760&&!ui.liveExpanded?'inert aria-hidden="true"':''}>${representatives.slice(0,5).map(t=>{const [label,color]=statusInfo(t);return `<button id="live-item-${t.id}" class="live-item ${color}" aria-haspopup="dialog" aria-expanded="${liveCard.taskId===t.id}" data-action="task" data-task="${t.id}" aria-label="${esc(AGENTS[t.agent].name+' '+t.title+' '+label)}">${icon(AGENTS[t.agent].icon)}<span>${AGENTS[t.agent].short||'小艺'}${t.status==='result'?'有新结果':t.status==='auth'?'待授权':t.status==='input'?'待补充':t.status==='failed'?'失败':t.status==='pausing'?'待暂停':'进行中'}</span></button>`;}).join('')}</div><button class="live-more" data-action="bot" aria-label="在 Bot 查看全部任务">${icon('right')}</button></aside>`;
}
function desktopShortcuts(){const copy=state.mode==='ai'?AI_DESKTOP_COPY:NORMAL_DESKTOP_COPY;return `<nav class="desktop-shortcuts" aria-label="桌面快捷方式"><button data-action="app" data-app="files">${appIcon('files')}<span>我的文件</span></button><button data-action="editor">${appIcon('editor')}<span>新品发布计划</span></button><button data-action="guide">${appIcon('shield')}<span>体验指南</span></button></nav><div class="desktop-signature" data-mode="${state.mode}"><span class="signature-ring">${icon('ring')}</span><p title="${esc(copy)}">${esc(copy)}</p></div>`;}
function controls(id){return `<div class="window-controls"><button data-action="minimize" data-window="${id}" aria-label="最小化窗口" class="min-control"><span></span></button><button data-action="maximize" data-window="${id}" aria-label="切换窗口大小" class="max-control"><span></span></button><button data-action="close" data-window="${id}" aria-label="关闭窗口" class="close-control">${icon('close')}</button></div>`;}
function windowMarkup(w){
 let title,body,smallIcon;
 if(w.id==='bot'){title=BOT_WINDOW_TITLE;smallIcon='bot';body=botBody();}
 else if(w.id.startsWith('doc-')){title=state.drafts[w.output]?.title||'任务文档';smallIcon='editor';body=editorBody(w.output,w.id);}
 else if(w.id==='editor'){title=state.drafts[ui.activeDraft]?.title||'文稿';smallIcon='editor';body=editorBody(ui.activeDraft,w.id);}
 else if(w.app==='editor'){title='Office Word';smallIcon='editor';body=editorBody('personal',w.id);}
 else if(w.id==='computer'){title='Computer Use';smallIcon='computer';body=computerBody();}
 else if(w.id==='output'){title='目标输出';smallIcon='output';body=outputBody();}
 else if(w.id==='guide'){title='体验指南';smallIcon='shield';body=guideBody();}
 else if(w.id.startsWith('agent-')){const a=w.id.slice(6);title=AGENTS[a].name;smallIcon=AGENTS[a].icon;body=agentBody(a);}
 else {const app=w.app||w.id.slice(4);title=APP_NAMES[app];smallIcon=app;body=ordinaryBody(app);}
 return `<section class="window ${w.id==='bot'?'bot-window':''} ${w.maximized?'maximized':''}" data-window="${w.id}" style="--wx:${w.x}px;--wy:${w.y}px;--ww:${w.w}px;--wh:${w.h}px;z-index:${w.z}" aria-label="${esc(title)}窗口"><header class="titlebar" data-drag="${w.id}"><div class="window-title">${w.id==='bot'?'<button class="mobile-tree" data-action="toggle-tree" aria-label="打开工作空间目录" aria-expanded="'+ui.sidebar+'">'+icon('grid')+'</button>':''}${icon(smallIcon)}<strong ${w.id==='bot'?`title="${esc(title)}"`:''}>${esc(title)}</strong>${w.id==='bot'?'':'<span class="window-subtitle">模拟</span>'}</div>${controls(w.id)}</header>${body}</section>`;
}
function tree(){return `<aside class="bot-sidebar ${ui.sidebar?'expanded':''}" ${innerWidth<=540&&!ui.sidebar?'inert aria-hidden="true"':''}><div class="sidebar-brand">${appIcon('bot','small')}<div>个人工作空间<small>仅保存在这台浏览器</small></div></div><nav class="center-tabs" aria-label="工作空间视图">${[['tree','任务'],['security','任务安全中心'],['agents','Agent 任务中心']].map(([id,name])=>`<button data-action="center-tab" data-tab="${id}" aria-pressed="${(ui.centerTab||'tree')===id}">${name}</button>`).join('')}</nav><div class="tree-label">工作空间</div><button class="tree-heading ${ui.section==='goals'?'chosen':''}" id="goals-toggle" data-action="toggle-goals" aria-expanded="${!state.goalsCollapsed}" aria-controls="goals-children">${icon('goal')}<span>任务</span><small>${state.goals.length}</small>${icon('chevron')}</button><div id="goals-children" class="goal-tree" ${state.goalsCollapsed?'hidden inert':''}>${state.goals.map(g=>`<button data-action="goal" data-goal="${g.id}" class="goal-link ${ui.section==='goals'&&state.selectedGoal===g.id?'selected':''}"><span class="tree-stem task-state-dot ${goalStatus(state,g.id)[0]}" title="${goalStatus(state,g.id)[1]}" aria-label="${goalStatus(state,g.id)[1]}"></span><span class="goal-name">${esc(g.name)}</span>${goalAgentIcons(g.id)}</button>`).join('')}</div><button class="tree-heading ${ui.section==='ideas'?'chosen':''}" id="ideas-toggle" data-action="toggle-ideas" aria-expanded="${!state.ideasCollapsed}" aria-controls="ideas-children">${icon('ideas')}<span>灵感想法</span><small>${state.ideas.length}</small>${icon('chevron')}</button><div id="ideas-children" class="ideas-tree" ${state.ideasCollapsed?'hidden inert':''}>${state.ideas.map(i=>`<button id="idea-${esc(i.id)}" class="idea-link ${ui.section==='ideas'&&state.selectedIdea===i.id?'selected':''}" data-action="idea" data-idea="${esc(i.id)}" title="${esc(i.name)}" ${ui.section==='ideas'&&state.selectedIdea===i.id?'aria-current="page"':''}><span class="tree-stem"></span><span>${esc(i.name)}</span></button>`).join('')}</div><button class="tree-heading ${ui.section==='todo'?'chosen':''}" data-action="section" data-section="todo">${icon('check')}<span>待办</span></button><button class="tree-heading ${ui.section==='connect'?'chosen':''}" id="connect-toggle" data-action="toggle-connect" aria-expanded="${!state.connectCollapsed}" aria-controls="connect-children">${icon('connect')}<span>Connect</span>${icon('chevron')}</button><div id="connect-children" class="connect-tree" ${state.connectCollapsed?'hidden inert':''}>${Object.entries(CONNECTIONS).map(([k,n])=>`<button data-action="connection" data-connection="${k}" class="connection-link ${ui.section==='connect'&&ui.connection===k?'selected':''}">${icon(k==='computer'?'computer':k==='mail'?'mail':'chat')}<span>${n}</span><span class="disconnected-dot" title="未连接"></span></button>`).join('')}</div><div class="sidebar-bottom">${icon('shield')}<span>本地模拟 · 无外部连接</span></div></aside>`;}
function botBody(){
 if(ui.centerTab&&ui.centerTab!=='tree')return centerBody();
 const g=currentGoal(),isGoal=ui.section==='goals',isIdeas=ui.section==='ideas',isTodo=ui.section==='todo';
 const idea=isIdeas?state.ideas.find(i=>i.id===state.selectedIdea):null;
 const channel=isTodo?'todo':isIdeas?ideaChannel(idea?.id):'connect-'+ui.connection;
 const title=isGoal?g.name:isTodo?'待办':isIdeas?(idea?.name||'灵感想法'):CONNECTIONS[ui.connection];
 const subtitle=isTodo?'在这里记录待办事项。仅保存在本机。':isGoal?g.subtitle:isIdeas?(idea?'想法记录 · 内容待补充':'把还没成形的想法，留给以后的自己。'):'未连接真实账号，仅演示会话和任务归属。';
 const messages=isGoal?g.messages:(state.channels[channel]||(isTodo?[{role:'bot',text:'暂无待办记录，可以先记下一句。',time:'现在'}]:isIdeas?[{role:'bot',text:'这个想法还没有内容。可以先记下一句。',time:'现在'}]:[{role:'bot',text:`${title} 尚未连接。你可以在这里留下演示消息，不会进行真实授权或发送。`,time:'现在'}]));
 const count=state.outputs.filter(o=>o.goal===g.id).length;
 return `<div class="bot-layout">${tree()}<div class="bot-main"><header class="conversation-header"><div><div class="conversation-kicker">${isGoal?'任务 · 长期会话':isIdeas?'灵感想法 · 灵感会话':isTodo?'待办 · 本地记录':'CONNECT · 连接演示'}</div><h1>${esc(title)}</h1>${isGoal?`<div class="goal-agents"><span>协作 Agent</span>${collaborators(g.id)}</div>`:''}<p>${esc(subtitle)}</p></div>${isGoal?`<div class="goal-header-actions">${safetyIndicator(g.id)}<button class="button output-button" data-action="outputs" data-goal="${g.id}">${icon('output')}<span>查看输出</span><span class="count">${count}</span></button></div>`:`<span class="offline-badge">${isIdeas||isTodo?'本地记录':'未连接'}</span>`}</header><div class="conversation-scroll" id="conversation-scroll"><div class="date-line"><span>${isGoal&&g.id==='launch'?'保留上次的思路':'今天 · 接着上次继续'}</span></div>${messages.map(m=>m.role==='handoff'?`<div class="handoff-note">${icon('connect')}<span>${esc(m.text)}</span></div>`:`<article class="message ${m.role}">${m.role==='bot'?appIcon('bot','avatar'):''}<div class="message-content"><div class="message-meta">${m.role==='bot'?'Bot':'你'}<time>${esc(m.time)}</time></div><div class="message-bubble">${esc(m.text)}</div></div></article>`).join('')}${isGoal?`<div class="goal-task-strip"><span>此目标的任务</span>${state.tasks.filter(t=>t.goal===g.id).slice(-4).map(t=>`<button data-action="task" data-task="${t.id}"><span class="tiny-dot ${statusInfo(t)[1]}"></span>${esc(t.title.slice(0,12))}${icon('right')}</button>`).join('')}</div>`:''}</div><div class="composer-area">${isGoal?'<button class="test-prompt" data-action="test-command">'+icon('plus')+'<span>试一下：研究桌面 AI，写一份评审简报</span></button>':''}<form id="bot-form" class="bot-composer" data-form="bot"><textarea id="bot-input" rows="2" aria-label="给 Bot 的指令" placeholder="${isGoal?'继续这个目标，或交给 Bot 一个新任务…':'留下消息，稍后继续…'}">${esc(ui.botInput)}</textarea><div class="composer-bottom"><span>${icon('connect')}${isGoal?'Bot 会协调合适的 Agent':'消息仅保存于本机'}</span><button type="submit" class="send-button" aria-label="发送 Bot 指令" ${!ui.botInput.trim()?'disabled':''}>${icon('arrow')}</button></div></form><p class="composer-footnote">所有任务均为模拟，不调用真实 Agent，不上传资料。</p></div></div></div>`;
}
function editorBody(draftId=ui.activeDraft,windowId='editor'){const d=state.drafts[draftId]||state.drafts.personal;return `<div class="editor-toolbar"><span>正文</span><span class="toolbar-rule"></span><span>思源黑体</span><span>16</span><strong>B</strong><em>I</em><span>U</span><span class="toolbar-rule"></span>${icon('more')}<span class="save-indicator">${icon('check')}已保存在本机</span></div><div class="editor-layout"><aside class="editor-sidebar"><span class="tree-label">文档目录</span><button class="selected">${icon('editor')}${esc(d.title.slice(0,11))}</button><span>工作草稿</span><span>本地自动保存</span></aside><div class="paper-wrap"><div class="paper-label">可继续编辑 · 重复打开保留你的修改</div><textarea id="draft-${esc(windowId)}" data-draft-id="${esc(draftId)}" class="paper" aria-label="草稿内容" spellcheck="false">${esc(d.text)}</textarea></div></div><footer class="editor-footer"><span>${[...d.text].length} 字 · 本地草稿</span><span>查看与编辑不代表接受或发布</span></footer>`;}
function agentBody(agent){const tasks=state.tasks.filter(t=>t.agent===agent);const t=tasks.find(t=>t.id===ui.activeTasks[agent])||tasks[0];ui.activeTasks[agent]=t?.id;
 return `<div class="agent-layout"><aside class="agent-task-list"><div class="tree-label">${tasks.length} 项任务</div>${tasks.map(x=>`<button data-action="task" data-task="${x.id}" class="agent-task-link ${x.id===t?.id?'selected':''}"><strong>${esc(x.title)}</strong>${badge(x)}<small>${esc(state.goals.find(g=>g.id===x.goal)?.name)}</small></button>`).join('')}</aside><div class="task-detail" data-task-id="${t?.id}">${t?taskDetail(t)+`<section class="task-window-group"><h3>此任务的工作窗口</h3>${taskWindows(t).map(windowTile).join('')}${state.session.task===t.id?windowTile({id:'computer'}):''}</section>`:'<p>暂时没有任务。</p>'}</div></div>`;
}
function taskSupplements(t){return t.instructions?.length?`<section class="task-supplements"><h3>此任务的补充指令 · 模拟</h3>${t.instructions.map(i=>`<p>${esc(i.text)}</p>`).join('')}</section>`:'';}
function taskDetail(t){const output=state.outputs.find(o=>o.id===t.outputId);return `<div class="task-eyebrow">${AGENTS[t.agent].name} <span>/</span> ${esc(state.goals.find(g=>g.id===t.goal)?.name)}</div><div class="task-title-row">${botSource(t)}<h2>${esc(t.title)}</h2>${badge(t)}</div>${permissionView(t,AGENTS[t.agent].name)}<p class="task-step">${icon(statusInfo(t)[2])}<span>${esc(t.step)}</span></p><div class="task-divider"></div>${t.status==='auth'?`<div class="permission-box"><span class="permission-icon">${icon('shield')}</span><h3>需要你确认本次操作</h3><p>允许小艺读取内置的模拟资料，用于「${esc(t.title)}」。只更新此原型的本地状态。</p><div class="permission-scope">演示资料集 · 仅本次 · 不访问磁盘</div><div class="action-row"><button class="button primary" data-action="authorize" data-task="${t.id}" data-allow="yes">允许本次模拟</button><button class="button" data-action="authorize" data-task="${t.id}" data-allow="no">拒绝本次</button></div></div>`:t.status==='input'?`<h3>这份建议，主要给谁看？</h3><p class="muted-text">补充后继续这项任务，其他任务不受影响。</p><div class="choice-options">${['专业用户','个人用户'].map(c=>`<label><input type="radio" name="audience" value="${c}" ${ui.choice===c?'checked':''}><span><strong>${c}</strong><small>${c==='专业用户'?'重视效率、协作与可控性':'重视易用性与日常体验'}</small></span></label>`).join('')}</div><button class="button primary" data-action="audience" data-task="${t.id}">补充并继续</button>`:t.status==='failed'?`<div class="failure-box">${icon('alert')}<h3>这一步没有完成</h3><p>内置模拟素材解析失败。任务与上下文已保留，可安全重试。</p><button class="button primary" data-action="retry" data-task="${t.id}">${icon('refresh')}重试这项任务</button></div>`:output?`<div class="output-preview-head"><span>输出 · 版本 ${output.version}</span><span>${t.unread?'未读':'已查看，未接受或发布'}</span></div><pre class="result-content">${esc(output.content)}</pre><div class="action-row"><button class="button primary" data-action="draft" data-output="${output.id}">${icon('editor')}在文稿中打开草稿</button><button class="button" data-action="outputs" data-goal="${t.goal}">所有版本</button></div>`:t.kind==='computer'?`<div class="computer-summary">${appIcon('computer')}<div><h3>正在使用模拟 Computer Use</h3><p>会话 ${esc(state.session.id)} 持续在线。你可以查看操作，或请求接管。</p></div></div><button class="button primary" data-action="computer">${icon('computer')}查看电脑操作</button>`:t.denied?`<p>你已拒绝本次模拟授权，任务保持暂停。</p><button class="button" data-action="reauthorize" data-task="${t.id}">重新请求模拟授权</button>`:`<div class="activity-step"><span class="activity-orbit"></span><div><h3>${t.status==='done'?'已交接，记录保留':'Agent 正在继续这项工作'}</h3><p>${esc(t.step)}</p></div></div>`}${taskSupplements(t)}<div class="task-footnote">${icon('shield')}模拟任务 · 关闭窗口只隐藏面板</div>`;}
function computerBody(){const s=state.session;const t=state.tasks.find(t=>t.id===s.task);const phase={agent:['Agent 正在操作','blue'],requesting_human:['等待暂停确认','yellow'],human:['你正在接管','muted'],requesting_agent:['等待交还确认','blue']}[s.phase];return `<div class="computer-topline"><div>${appIcon(s.agent,'small')}<span><strong>${AGENTS[s.agent].name}</strong><small>${esc(t.title)} · 同一会话持续在线</small></span></div><span class="status ${phase[1]}">${icon(s.phase==='human'?'hand':'computer')}${phase[0]}</span></div><div class="computer-layout"><div class="simulation-screen"><div class="sim-browserbar"><span class="browser-dots"><i></i><i></i><i></i></span><span class="sim-url">${icon('shield')}local-demo / interaction-notes</span><span class="simulation-label">模拟屏幕</span></div><div class="sim-page"><span class="sim-eyebrow">RESEARCH NOTES</span><h2>桌面 AI 交互对比</h2><p>一处记录，交接时带走完整上下文。</p><div class="sim-table"><div><strong>观察维度</strong><strong>当前结论</strong></div><div><span>任务状态</span><span>区分运行、确认和结果</span></div><div><span>控制权</span><span>暂停确认后再接管</span></div></div><label for="manual-notes">这次对比的重点 <span>上下文 v${s.contextVersion}</span></label><textarea id="manual-notes" ${s.phase!=='human'?'disabled':''} aria-label="人工编辑模拟页面">${esc(ui.manual)}</textarea><button class="button ${s.phase==='human'?'primary':''}" data-action="manual-save" ${s.phase!=='human'?'disabled':''}>${icon('check')}保存到模拟页面</button><small>${s.phase==='human'?'修改后保存，再交还给 Agent 继续。':'当前仅供查看；暂停确认后可编辑。'}</small></div></div><aside class="computer-inspector"><div class="controller-label">当前唯一控制者</div><div class="controller">${icon(s.controller==='human'?'hand':'bot')}<strong>${s.controller==='human'?'你':AGENTS[s.agent].name}</strong></div><p class="controller-step">${esc(t.step)}</p>${s.phase==='agent'?'<button class="button primary takeover-button" data-action="takeover">'+icon('hand')+'请求人工接管</button>':s.phase==='human'?'<button class="button primary takeover-button" data-action="handback">'+icon('play')+'交还给 Agent</button>':'<button class="button takeover-button" disabled>'+icon('clock')+(s.phase==='requesting_human'?'等待 Agent 暂停 ACK':'等待 Agent 接收 ACK')+'</button>'}<div class="session-meta"><span>会话保持在线</span><code>${s.id}</code><span>页面上下文</span><strong>v${s.contextVersion}</strong></div><div class="operation-heading">操作记录 <span>模拟</span></div><ol class="operation-log">${s.log.slice(-5).map((l,i)=>`<li><span>${String(Math.max(1,s.log.length-4)+i).padStart(2,'0')}</span>${esc(l)}</li>`).join('')}</ol></aside></div><div class="computer-footer">${icon('shield')}仅操作内置模拟页面，未控制本机或其他真实应用。关闭窗口不会取消任务或改变控制权。</div>`;}
function outputBody(){const g=state.goals.find(g=>g.id===ui.outputGoal);const outputs=state.outputs.filter(o=>o.goal===ui.outputGoal);const o=outputs.find(o=>o.id===ui.outputId)||outputs.at(-1);return `<div class="output-layout"><aside class="output-list"><div class="tree-label">${esc(g?.name)} · ${outputs.length} 个版本</div>${outputs.slice().reverse().map(x=>`<button data-action="output-version" data-output="${x.id}" class="${x.id===o?.id?'selected':''}">${icon('editor')}<span><strong>版本 ${x.version}</strong><small>${esc(x.title)}</small></span></button>`).join('')}</aside><div class="output-document">${o?`<div class="output-preview-head"><span>版本 ${o.version} · ${esc(o.created)}</span><span>已查看 · 未发布</span></div><pre class="result-content">${esc(o.content)}</pre><button class="button primary" data-action="draft" data-output="${o.id}">${icon('editor')}在文稿中打开草稿</button>`:`<div class="empty-state">${icon('output')}<h2>这个目标还没有输出</h2><p>在 Bot 发送测试指令，研究和写作完成后，版本会保存在这里。</p><button class="button" data-action="go-to-goal" data-goal="${ui.outputGoal}">回到目标会话</button></div>`}</div></div>`;}
function ordinaryBody(app){if(app==='files')return `<div class="ordinary-app"><h2>我的文件</h2><p>原型内的本地草稿和目标输出</p><div class="file-grid">${Object.entries(state.drafts).map(([id,d])=>`<button data-action="local-draft" data-draft="${esc(id)}">${appIcon('editor')}<strong>${esc(d.title)}</strong><small>本地草稿 · 自动保存</small></button>`).join('')}</div></div>`;return `<div class="ordinary-app"><div class="empty-state">${appIcon(app)}<h2>${APP_NAMES[app]}</h2><p>${app==='browser'?`这是模拟浏览器入口。${AGENTS[state.session.agent].name} 的操作可在 Computer Use 查看。`:app==='mail'?'邮箱尚未连接。可在 Bot 的 Connect 中体验本地会话。':'这是桌面交互原型中的普通应用入口。'}</p><button class="button" data-action="${app==='browser'?'computer':'bot'}">${app==='browser'?'查看模拟操作':'打开 Bot 工作空间'}</button><small>不访问真实应用或账号。</small></div></div>`;}
function guideBody(){return `<div class="guide-body"><div class="guide-hero">${appIcon('ring')}<div><h1>桌面依旧熟悉，工作可以继续。</h1><p>Demo 5 · 一个完全在本地运行的 AI Dock 交互原型。</p></div></div><div class="guide-steps"><button data-action="test-command">${icon('bot')}<div><strong>01 · 让 Bot 协调工作</strong><span>发送测试指令，观察研究 → 写作，再查看目标输出。</span></div>${icon('right')}</button><button data-action="computer">${icon('computer')}<div><strong>02 · 接管，再交还</strong><span>请求暂停 → 收到 ACK → 修改模拟页面 → 交还并继续。</span></div>${icon('right')}</button><button data-action="task" data-task="xiaoyi-auth">${icon('shield')}<div><strong>03 · 看见关键状态</strong><span>黄色待确认、绿色待查看、红色失败；点击进入准确任务。</span></div>${icon('right')}</button></div><div class="guide-note">悬停 Agent 图标可展开多项任务，点击或键盘 Tab 同样可用。普通应用顺序保持固定；关闭窗口只隐藏面板。草稿、会话和输出会在本机保存。</div></div>`;}
function agentDock(agent){const a=AGENTS[agent],tasks=state.tasks.filter(t=>t.agent===agent&&(!t.hoverHidden||[...ui.windows.values()].some(w=>w.task===t.id&&w.output)||state.session.task===t.id)),unread=tasks.filter(t=>t.unread).length,docs=[...ui.windows.values()].filter(w=>w.agent===agent&&w.output),computer=state.session.agent===agent;return `<div class="agent-anchor ${ui.hoveredAgent===agent?'hovering':''} ${ui.suppressedAgents.has(agent)?'hover-suppressed':''}" data-agent-owner="${agent}"><button class="dock-app" data-action="agent-preview" data-agent="${agent}" aria-label="${a.name}的任务" aria-expanded="${ui.pinnedAgent===agent}">${appIcon(agent)}<span class="dock-label">${a.short}</span>${unread?`<span class="notification-count">${unread}</span>`:''}</button><aside class="task-preview ${ui.pinnedAgent===agent?'pinned':''}" data-preview-width="${Math.min(tasks.length+docs.length+(computer?1:0),3)*258+56}" aria-label="${a.name}任务卡片"><header>${appIcon(agent,'small')}<div><strong>${a.name}</strong><small>${tasks.length} 项任务 · ${docs.length} 个文档窗口${computer?' · Computer Use':''}</small></div></header><div class="preview-task-list">${docs.map(w=>`<article class="preview-task independent-window-card" data-document-preview="${w.output}"><span class="preview-kind">${icon('editor')}文档窗口 · ${esc(state.tasks.find(t=>t.id===w.task)?.title)}</span>${windowTile(w)}</article>`).join('')}${computer?`<article class="preview-task independent-window-card" data-computer-preview="${state.session.id}"><span class="preview-kind">${icon('computer')}Computer Use · ${esc(state.tasks.find(t=>t.id===state.session.task)?.title)}</span>${windowTile({id:'computer'})}</article>`:''}${tasks.slice().reverse().map(t=>`<article class="preview-task task-context">${botSource(t)}<button class="task-open" data-action="task" data-task="${t.id}"><strong>${esc(t.title)}</strong>${badge(t)}<p>${esc(t.step)}</p><small>${esc(state.goals.find(g=>g.id===t.goal)?.name)}${icon('right')}</small></button>${t.outputId?`<button class="output-link" data-action="draft" data-output="${t.outputId}">${icon('editor')}查看输出文档</button>`:''}</article>`).join('')}</div><footer>任务进度与打开窗口分别成卡 · 横向查看更多</footer></aside></div>`;}
function ordinaryDock(app){const wins=[...ui.windows.values()].filter(w=>w.app===app||(app==='editor'&&w.id==='editor'));return `<div class="ordinary-anchor"><button class="dock-app ${wins.length?'opened':''}" data-action="app" data-app="${app}" aria-label="打开${APP_NAMES[app]}">${appIcon(app)}<span class="dock-label">${APP_NAMES[app]}</span></button>${wins.length?`<aside class="ordinary-preview"><strong>${APP_NAMES[app]} · ${wins.length} 个窗口</strong>${wins.map(windowTile).join('')}<button class="output-link" data-action="new-app-window" data-app="${app}">${icon('plus')}新建窗口</button><small>运行中临时显示 · 不支持固定</small></aside>`:''}</div>`;}
function dock(){const isAi=state.mode==='ai';const s=state.session;return `<nav data-flip-phase="${dockFlip.phase}" aria-busy="${dockFlip.active}" ${dockFlip.active?'inert':''} class="dock ${isAi?'ai-dock':'normal-dock'}" aria-label="${isAi?'AI':'普通应用'} Dock"><button class="dock-scroll scroll-left" data-action="dock-scroll" data-dir="-1" aria-label="向左滚动 Dock">${icon('chevron')}</button><div class="dock-body" tabindex="0" aria-label="Dock 横向滚动区域"><button class="dock-app start-app" data-action="launcher" aria-label="开始">${appIcon('ring')}<span class="dock-label">开始</span></button>${isAi?`<button class="dock-app ${windowVisible(ui,'bot')?'opened':''}" data-action="bot" aria-label="打开 Bot">${appIcon('bot')}<span class="dock-label">Bot</span></button><form class="command-form" data-form="dock"><label class="agent-select">${appIcon(ui.agent,'small')}<span class="selector-selected" aria-hidden="true">${AGENTS[ui.agent].selectorLabel}</span><select id="dock-agent" aria-label="指令 Agent：${esc(AGENTS[ui.agent].name)}" title="${esc(AGENTS[ui.agent].name)}">${['xiaoyi',...AGENT_ORDER].map(a=>`<option value="${a}" ${a===ui.agent?'selected':''}>${AGENTS[a].name}</option>`).join('')}</select>${icon('chevron')}</label><input id="dock-input" aria-label="Dock 指令输入" placeholder="把下一件事，交给 AI…" value="${esc(ui.dockInput)}" autocomplete="off"><button type="button" class="mic-button" data-action="mic" aria-label="模拟语音输入">${icon('mic')}</button><button type="submit" class="dock-send" aria-label="发送 Dock 指令" ${!ui.dockInput.trim()?'disabled':''}>${icon('arrow')}</button></form><span class="dock-separator"></span>${AGENT_ORDER.map(agentDock).join('')}${ORDINARY_APPS.filter(a=>runningAppKeys(ui.windows).includes(a)).map(ordinaryDock).join('')}`:`<span class="dock-separator"></span>${ORDINARY_APPS.map(ordinaryDock).join('')}`}${s?`<span class="dock-separator computer-separator"></span><button class="dock-app computer-dock" data-action="computer" aria-label="查看 ${AGENTS[s.agent].name} 的 Computer Use" title="${AGENTS[s.agent].name} · 模拟 Computer Use">${appIcon('computer')}<span class="invoker-badge ${s.agent}">${icon(AGENTS[s.agent].icon)}</span><span class="dock-label">Computer</span><span class="controller-dot ${s.controller==='human'?'human':''}"></span></button>`:''}<span class="dock-separator"></span><div class="dock-mode-tools"><button class="mode-button" data-action="mode" data-mode="${isAi?'normal':'ai'}" aria-label="${isAi?'返回普通 Dock':'切换 AI Dock'}">${isAi?'应用':'AI'}<span class="mode-dot ${isAi?'':'active'}"></span></button></div></div><button class="dock-scroll scroll-right" data-action="dock-scroll" data-dir="1" aria-label="向右滚动 Dock">${icon('chevron')}</button></nav><div class="dock-caption">${isAi?'AI 模式 · 固定 Agent，任务持续在线':'普通应用 · 顺序保持不变'} <span>·</span> 交互均为模拟</div>`;}
function launchers(){return `${ui.launcher?`<aside class="launcher glass-popover"><header>${icon('ring')}<strong>开始</strong><button data-action="launcher" aria-label="收起开始菜单">${icon('close')}</button></header><div class="launcher-apps"><button data-action="bot">${appIcon('bot')}Bot</button>${ORDINARY_APPS.map(a=>`<button data-action="app" data-app="${a}">${appIcon(a)}${APP_NAMES[a]}</button>`).join('')}</div><div class="tree-label">继续你的目标</div>${state.goals.map(g=>`<button class="launcher-goal" data-action="go-to-goal" data-goal="${g.id}">${icon('goal')}${esc(g.name)}${icon('right')}</button>`).join('')}<footer><span>${icon('shield')}原型数据 · 本地保存</span><button data-action="guide">体验指南</button></footer></aside>`:''}${ui.apps?`<aside class="apps-popover glass-popover"><h3>普通应用</h3><div class="launcher-apps">${ORDINARY_APPS.map(a=>`<button data-action="app" data-app="${a}">${appIcon(a)}${APP_NAMES[a]}</button>`).join('')}</div><small>保留原来的应用顺序</small></aside>`:''}`;}
function render({forceDock=false}={}){
 const focused=document.activeElement;const focusId=focused?.id;let selection;try{selection=[focused.selectionStart,focused.selectionEnd];}catch{}
 const scrolls=[...document.querySelectorAll('.conversation-scroll,.result-content,.task-detail,.preview-task-list,.paper,.operation-log')].map(el=>[el.id||el.className,el.scrollTop]);
 desktopContent.innerHTML=statusBar()+notificationPanel()+desktopShortcuts()+`<div class="window-stage">${[...ui.windows.values()].filter(w=>!w.minimized).map(windowMarkup).join('')}</div>`+launchers();
 dockMount.dataset.flipping=String(dockFlip.active);
 if(!dockFlip.active||forceDock)dockMount.innerHTML=dock();
 for(const [key,top] of scrolls){const el=[...document.querySelectorAll('.conversation-scroll,.result-content,.task-detail,.preview-task-list,.paper,.operation-log')].find(e=>(e.id||e.className)===key);if(el)el.scrollTop=top;}
 if(focusId){const el=document.getElementById(focusId);if(el&&!el.disabled){el.focus({preventScroll:true});if(selection?.[0]!=null)try{el.setSelectionRange(...selection);}catch{}}}
 const botWindow=$('.bot-window');if(botWindow)botWindow.style.setProperty('--bot-title-height',botWindow.querySelector('.titlebar').getBoundingClientRect().height+'px');
 const liveItems=$('.live-items');if(liveItems){liveItems.scrollLeft=ui.liveScroll;liveItems.addEventListener('scroll',()=>{ui.liveScroll=liveItems.scrollLeft;liveCard.update();},{passive:true});}
 const scroll=$('.dock-body');if(scroll){scroll.closest('.dock').classList.toggle('has-overflow',scroll.scrollWidth>scroll.clientWidth+1);scroll.scrollLeft=ui.dockScroll||0;scroll.addEventListener('scroll',()=>{ui.dockScroll=scroll.scrollLeft;syncAgentPreviews();},{passive:true});}
 syncAgentPreviews();
 liveCard.update();
}
function syncAgentPreviews(){
 const focused=document.activeElement?.closest?.('.agent-anchor')?.dataset.agentOwner;
 const owner=ui.hoveredAgent||ui.pinnedAgent||ui.focusedAgent||focused;
 for(const anchor of document.querySelectorAll('.agent-anchor')){
  const agent=anchor.dataset.agentOwner,preview=anchor.querySelector('.task-preview');
  const margin=innerWidth<=760?12:16,width=Math.min(Number(preview.dataset.previewWidth),innerWidth-margin*2),r=anchor.getBoundingClientRect();
  const left=Math.max(margin,Math.min(innerWidth-margin-width,r.left+r.width/2-width/2));
  preview.style.setProperty('--preview-width',width+'px');preview.style.setProperty('--preview-left',(left-anchor.closest('.dock').getBoundingClientRect().left)+'px');
  anchor.classList.toggle('preview-owner',agent===owner);
  anchor.querySelector('[data-action="agent-preview"]').setAttribute('aria-expanded',String(agent===owner&&!ui.suppressedAgents.has(agent)));
 }
}
function send(text,agent='xiaoyi'){
 const value=text.trim();if(!value)return;
 if(ui.section==='goals')dispatch({type:'SEND',text:value,goal:state.selectedGoal,agent,source:agent==='xiaoyi'?'bot':'manual'},{renderNow:false});
 else dispatch({type:'CHANNEL_SEND',text:value,channel:ui.section==='todo'?'todo':ui.section==='ideas'?ideaChannel(state.selectedIdea):'connect-'+ui.connection},{renderNow:false});
 ui.botInput='';ui.dockInput='';ui.hangerOpen=false;showWindow('bot');render();const scroll=$('#conversation-scroll');if(scroll)scroll.scrollTop=scroll.scrollHeight;toast(ui.section==='goals'?(['xiaoyi','research'].includes(agent)?'模拟任务已交给 Workbuddy，随后交接给千问':'模拟任务已交给'+AGENTS[agent].name):'消息已保存在本地会话');
}
desktop.addEventListener('click',e=>{
 const b=e.target.closest('[data-action]');if(!b||b.disabled)return;
 const a=b.dataset.action;
 if(dockFlip.active&&b.closest('.dock'))return;
 const launcher=!!b.closest('.dock,.desktop-shortcuts,.launcher');
 if(['bot','computer','app','editor','guide','agent-preview','restore-window','outputs','draft','local-draft'].includes(a))ui.hangerOpen=false;
 if(a==='notifications'){ui.hangerOpen=false;ui.notifications=!ui.notifications;ui.liveExpanded=false;liveCard.dismiss(false);render();if(ui.notifications)$('#notification-heading')?.focus();else $('#notification-toggle')?.focus();return;}
 if(a==='live-summary'){ui.notifications=false;if(innerWidth<=760){ui.liveExpanded=!ui.liveExpanded;render();}else{render();document.querySelector('.live-item')?.focus();}return;}
 if(a==='dock-scroll'){b.closest('.dock').querySelector('.dock-body').scrollBy({left:Number(b.dataset.dir)*250,behavior:'smooth'});return;}
 if(a==='permission'){dispatch({type:'PERMISSION',task:b.dataset.task,op:b.dataset.op});return;}
 if(a==='safety'){openTask(b.dataset.task);return;}
 if(a==='center-tab'){ui.centerTab=b.dataset.tab;ui.sidebar=false;render();return;}
 if(a==='center-filter'){ui.centerFilter=b.dataset.filter;render();return;}
 if(a==='pin-task'){dispatch({type:'PIN_TASK',task:b.dataset.task});return;}
 if(a==='task'){openTask(b.dataset.task);return;}
 if(a==='bot'){if(launcher)toggleWindow(ui,launcherWindow('bot'),showWindow);else showWindow('bot');ui.launcher=false;render();return;}
 if(a==='toggle-ideas'){dispatch({type:'TOGGLE_IDEAS'});return;}
 if(a==='idea'){ui.sidebar=false;ui.section='ideas';ui.botInput='';dispatch({type:'IDEA_SELECT',idea:b.dataset.idea});return;}
 if(a==='toggle-goals'){dispatch({type:'TOGGLE_GOALS'});return;}
 if(a==='toggle-connect'){dispatch({type:'TOGGLE_CONNECT'});return;}
 if(a==='toggle-tree'){ui.sidebar=!ui.sidebar;render();return;}
 if(a==='computer'){if(launcher)toggleWindow(ui,launcherWindow('computer'),showWindow);else showWindow('computer');render();return;}
 if(a==='editor'){toggleWindow(ui,launcherWindow('app','editor'),showWindow);render();return;}
 if(a==='guide'){if(launcher)toggleWindow(ui,'guide',showWindow);else showWindow('guide');ui.launcher=false;render();return;}
 if(a==='restore-window'){showWindow(b.dataset.window);ui.pinnedAgent=null;render();return;}
 if(a==='new-app-window'){const app=b.dataset.app;showWindow('app-'+app+'-'+Date.now(),{app});ui.launcher=false;render();return;}
 if(a==='close'){const w=ui.windows.get(b.dataset.window);if(w?.app||w?.id==='editor'||w?.id.startsWith('doc-'))ui.windows.delete(b.dataset.window);else closeWindow(ui,b.dataset.window);if(w?.output&&canDismissTaskHover(ui.windows,state.session,w.task))dispatch({type:'DISMISS_TASK_HOVER',task:w.task},{renderNow:false});render();return;}
 if(a==='minimize'){ui.windows.get(b.dataset.window).minimized=true;render();return;}
 if(a==='maximize'){const w=ui.windows.get(b.dataset.window);w.maximized=!w.maximized;render();return;}
 if(a==='launcher'){toggleStart(ui);ui.apps=false;render();return;}
 if(a==='apps'){ui.apps=!ui.apps;ui.launcher=false;render();return;}
 if(a==='app'){openApp(b.dataset.app);return;}
 if(a==='mode'){dockFlip.change(b.dataset.mode);return;}
 if(a==='agent-preview'){ui.pinnedAgent=ui.pinnedAgent===b.dataset.agent?null:b.dataset.agent;ui.suppressedAgents.delete(b.dataset.agent);ui.launcher=false;render();return;}
 if(a==='goal'||a==='go-to-goal'){ui.sidebar=false;ui.section='goals';ui.botInput='';dispatch({type:'GOAL',goal:b.dataset.goal},{renderNow:false});if(a==='go-to-goal')showWindow('bot');ui.launcher=false;render();const scroll=$('#conversation-scroll');if(scroll)scroll.scrollTop=scroll.scrollHeight;return;}
 if(a==='section'){if(b.dataset.section==='ideas')dispatch({type:'IDEA_SELECT',idea:null,expand:true},{renderNow:false});else dispatch({type:'IDEA_LEAVE'},{renderNow:false});if(b.dataset.section!=='goals')ui.sidebar=false;ui.section=b.dataset.section;ui.botInput='';render();return;}
 if(a==='connection'){dispatch({type:'IDEA_LEAVE'},{renderNow:false});ui.sidebar=false;ui.section='connect';ui.connection=b.dataset.connection;ui.botInput='';render();return;}
 if(a==='test-command'){ui.section='goals';send('研究桌面 AI 交互，并写一份评审简报');return;}
 if(a==='outputs'){openOutput(b.dataset.goal);return;}
 if(a==='output-version'){ui.outputId=b.dataset.output;dispatch({type:'VIEW_OUTPUT',output:ui.outputId},{renderNow:false});render();return;}
 if(a==='draft'){openDraft(b.dataset.output);return;}
 if(a==='local-draft'){if(state.outputs.some(o=>o.id===b.dataset.draft)){openDraft(b.dataset.draft);return;}ui.activeDraft=b.dataset.draft;showWindow('editor');render();return;}
 if(a==='authorize'){dispatch({type:'AUTHORIZE',task:b.dataset.task,allow:b.dataset.allow==='yes'});return;}
 if(a==='reauthorize'){dispatch({type:'REAUTHORIZE',task:b.dataset.task});return;}
 if(a==='audience'){dispatch({type:'INPUT',task:b.dataset.task,choice:ui.choice});return;}
 if(a==='retry'){dispatch({type:'RETRY',task:b.dataset.task});return;}
 if(a==='takeover'){dispatch({type:'TAKEOVER'});return;}
 if(a==='handback'){if(ui.manual!==state.session.manualText){toast('请先保存模拟页面的修改，再交还给 Agent');$('#manual-notes')?.focus();return;}dispatch({type:'HANDBACK'});return;}
 if(a==='manual-save'){const text=ui.manual.trim();if(!text){toast('请填写这次对比的重点');return;}dispatch({type:'MANUAL_EDIT',text});toast('模拟页面已保存，交还时会同步最新上下文');return;}
 if(a==='mic'){ui.dockInput='研究桌面 AI 交互，并写一份评审简报';render();toast('这是模拟语音输入，未请求麦克风或录音');}
});
desktop.addEventListener('submit',e=>{e.preventDefault();const form=e.target.dataset.form;if(form==='dock'){ui.section='goals';send(ui.dockInput,ui.agent);}else if(form==='bot')send(ui.botInput);});
desktop.addEventListener('input',e=>{
 if(e.target.id==='dock-input'){ui.dockInput=e.target.value;e.target.form.querySelector('[type="submit"]').disabled=!ui.dockInput.trim();}
 if(e.target.id==='bot-input'){ui.botInput=e.target.value;e.target.form.querySelector('[type="submit"]').disabled=!ui.botInput.trim();}
 if(e.target.id==='manual-notes')ui.manual=e.target.value;
 if(e.target.dataset.draftId){dispatch({type:'EDIT_DRAFT',id:e.target.dataset.draftId,text:e.target.value},{renderNow:false});e.target.closest('.window').querySelector('.editor-footer span').textContent=`${[...e.target.value].length} 字 · 本地草稿`;}
});
desktop.addEventListener('change',e=>{if(e.target.id==='dock-agent'){ui.agent=e.target.value;render();}if(e.target.name==='audience')ui.choice=e.target.value;});
desktop.addEventListener('keydown',e=>{if(e.target.id==='bot-input'&&e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();send(ui.botInput);}if(e.key==='Escape'){const closeNotifications=ui.notifications;ui.notifications=false;ui.liveExpanded=false;ui.sidebar=false;ui.pinnedAgent=null;ui.launcher=false;ui.apps=false;render();if(closeNotifications)$('#notification-toggle')?.focus();}});
let drag;
desktop.addEventListener('pointerdown',e=>{
 const section=e.target.closest('.window');if(section){const w=ui.windows.get(section.dataset.window);w.z=++ui.z;section.style.zIndex=w.z;}
 const bar=e.target.closest('[data-drag]');if(!bar||e.target.closest('button')||innerWidth<760||e.button!==0)return;
 const w=ui.windows.get(bar.dataset.drag);if(w.maximized)return;
 drag={id:w.id,x:e.clientX,y:e.clientY,startX:w.x,startY:w.y};bar.setPointerCapture(e.pointerId);e.preventDefault();
});
desktop.addEventListener('focusin',e=>{ui.focusedAgent=e.target.closest('.agent-anchor')?.dataset.agentOwner||null;if(ui.focusedAgent)ui.hoveredAgent=null;syncAgentPreviews();});
desktop.addEventListener('focusout',e=>{const from=e.target.closest('.agent-anchor'),to=e.relatedTarget?.closest?.('.agent-anchor');if(from&&from!==to){ui.focusedAgent=to?.dataset.agentOwner||null;syncAgentPreviews();}});
desktop.addEventListener('pointermove',e=>{const hovered=e.target.closest('.agent-anchor')?.dataset.agentOwner||null;if(ui.hoveredAgent!==hovered){ui.hoveredAgent=hovered;if(hovered&&ui.pinnedAgent!==hovered){ui.pinnedAgent=null;for(const preview of document.querySelectorAll('.task-preview.pinned'))preview.classList.remove('pinned');}for(const anchor of document.querySelectorAll('.agent-anchor'))anchor.classList.toggle('hovering',anchor.dataset.agentOwner===hovered);}for(const agent of ui.suppressedAgents){const anchor=document.querySelector(`[data-agent-owner="${agent}"]`);if(!anchor?.contains(e.target)){releaseAgentHover(ui,agent);anchor?.classList.remove('hover-suppressed');}}syncAgentPreviews();if(!drag)return;const w=ui.windows.get(drag.id);w.x=Math.max(0,Math.min(innerWidth-w.w,drag.startX+e.clientX-drag.x));w.y=Math.max(100,Math.min(innerHeight-170,drag.startY+e.clientY-drag.y));const el=document.querySelector(`.window[data-window="${w.id}"]`);el?.style.setProperty('--wx',w.x+'px');el?.style.setProperty('--wy',w.y+'px');});
desktop.addEventListener('pointerup',()=>{drag=null;});
desktop.addEventListener('pointercancel',()=>{drag=null;});
addEventListener('resize',()=>{for(const w of ui.windows.values()){w.w=Math.min(w.preferredW,innerWidth-36);w.h=Math.max(310,Math.min(w.preferredH,innerHeight-235));w.x=Math.max(12,Math.min(w.x,innerWidth-w.w-12));w.y=Math.max(110,Math.min(w.y,innerHeight-w.h-120));}render();});
setInterval(()=>{let next=reduce(state,{type:'TICK'});if(next!==state){const top=[...ui.windows.values()].filter(w=>!w.minimized).sort((a,b)=>a.z-b.z).at(-1);if(top?.id.startsWith('agent-')){const id=ui.activeTasks[top.id.slice(6)];if(next.tasks.some(t=>t.id===id&&t.status==='result'&&t.unread))next=reduce(next,{type:'VIEW',task:id});}state=next;saveState(localStorage,state);render();}},350);
// Demo 5 starts on the desktop; Bot and all inherited windows remain available from the Dock.
render();
if($('#conversation-scroll'))$('#conversation-scroll').scrollTop=$('#conversation-scroll').scrollHeight;

desktop.addEventListener('pointermove',e=>{const glass=e.target.closest('.ai-dock');if(!glass||motionPreference.matches)return;const r=glass.getBoundingClientRect();glass.style.setProperty('--glass-x',Math.round((e.clientX-r.left)/r.width*100)+'%');},{passive:true});

function safetyIndicator(goal){const candidates=state.tasks.filter(t=>t.goal===goal);const order={red:0,yellow:1,green:2};const t=candidates.sort((a,b)=>order[risk(permissionState(a))[0]]-order[risk(permissionState(b))[0]])[0];if(!t)return '<span>暂无权限请求</span>';const [c,r]=risk(permissionState(t));return `<button class="safety-indicator" data-action="safety" data-task="${t.id}" title="安全管家 · ${esc(r)}"><span class="safety-light ${c}"></span><span>${esc(r)}</span></button>`;}

function centerBody(){const security=ui.centerTab==='security',filter=ui.centerFilter||'All',tasks=security?securityTasks(state):centerTasks(state,filter);return '<div class="bot-layout">'+tree()+`<main class="task-center"><h1>${security?'任务安全中心':'Agent 任务中心'}</h1><p>${security?'查看当前任务风险与待确认范围；点击进入现有权限及 Context 界面。':'同一任务数据 · 选择卡片查看进度，实际打开输出才计为已读。'}</p>${security?'':`<nav class="center-filters" aria-label="任务筛选">${[['All','全部'],['Running','Running · 运行中'],['Blocked','Blocked · 需处理'],['Unread','Unread · 未读'],['Pinned','置顶'],['History','历史']].map(([id,n])=>`<button class="button" data-action="center-filter" data-filter="${id}" aria-pressed="${filter===id}">${n}</button>`).join('')}</nav>`}<div class="center-card-grid">${tasks.map(t=>{const [c,r]=risk(permissionState(t)),o=state.outputs.find(x=>x.id===t.outputId);return `<article class="center-task-card agent-${t.agent}"><div class="center-card-top">${appIcon(t.agent,'small')}<strong>${AGENTS[t.agent].name}</strong>${goalAgentIcons(t.goal)}</div><h2>${esc(t.title)}</h2><p>${security?`<span class="safety-light ${c}"></span> ${esc(r)}`:badge(t)}</p><p>${esc(t.step)}</p>${security?'<p>建议：限定本任务必要文件；扩展范围前确认。</p>':''}<div class="action-row"><button class="button" data-action="task" data-task="${t.id}">${security?'查看权限与 Context':'查看任务'}</button>${o?`<button class="button" data-action="draft" data-output="${o.id}">查看输出</button>`:''}<button class="button" data-action="pin-task" data-task="${t.id}" aria-pressed="${!!t.pinned}">${t.pinned?'取消置顶':'置顶'}</button></div></article>`}).join('')||'<p>当前没有此类任务。</p>'}</div></main></div>`; }
